import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 반려 시 personnel_appointment.status 체크 제약에 '반려'가 없어 상태 값은 바꾸지 않고 처리자·수정일시만 기록한다.
// 가정: 상신 문서번호는 'PA-' + 상신 시각 + 인사발령 ID로 채번한다 (채번 규칙 미정).
const WAITING = '대기';
const APPROVED = '승인';
const SUBMITTED_STATUS = '결재대기';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function isIntegerText(value: unknown): boolean {
  return typeof value === 'string' && /^[0-9]+$/.test(value);
}

@Controller('api/v1')
export class FnSfr01301Controller {
  @Get('/personnel-appointments')
  async listPersonnelAppointments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const q = checks.queryOf(req.query);
    const pageText = q['page'];
    const sizeText = q['size'];
    const status = q['status'];
    const employeeId = q['employeeId'];
    if (pageText !== undefined && pageText !== '' && !isIntegerText(pageText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 번호가 올바르지 않습니다.');
    }
    if (sizeText !== undefined && sizeText !== '' && !isIntegerText(sizeText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '페이지 크기가 올바르지 않습니다.');
    }
    if (employeeId !== undefined && employeeId !== '' && !isIntegerText(employeeId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '대상 임직원 ID가 올바르지 않습니다.');
    }
    if (status !== undefined && status !== '' && !['대기', '승인', '처리완료'].includes(String(status))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '발령 상태가 올바르지 않습니다.');
    }
    const page = pageText === undefined || pageText === '' ? 0 : Number(pageText);
    const requestedSize = sizeText === undefined || sizeText === '' ? DEFAULT_SIZE : Number(sizeText);
    const size = Math.min(Math.max(requestedSize, 1), MAX_SIZE);
    const params = {
      status: status === undefined || status === '' ? null : String(status),
      employeeId: employeeId === undefined || employeeId === '' ? null : String(employeeId),
      size,
      offset: page * size,
    };
    return transaction(async (db) => {
      const where = `(CAST(:status AS text) IS NULL OR status = CAST(:status AS text))
        AND (CAST(:employeeId AS bigint) IS NULL OR employee_id = CAST(:employeeId AS bigint))`;
      const countRows = await db.query(
        `SELECT COUNT(*) AS "total" FROM personnel_appointment WHERE ${where}`,
        params,
      );
      const items = await db.query(
        `SELECT personnel_appointment_id AS "personnelAppointmentId",
          employee_id AS "employeeId",
          appointment_type AS "appointmentType",
          appointment_date AS "appointmentDate",
          new_position_name AS "newPositionName",
          status AS "status",
          approval_document_id AS "approvalDocumentId"
        FROM personnel_appointment
        WHERE ${where}
        ORDER BY personnel_appointment_id DESC
        LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        params,
      );
      return { items, page, size, total: Number(countRows[0]['total']) };
    });
  }

  @Post('/personnel-appointments/:personnelAppointmentId/approve')
  @HttpCode(200)
  async approvePersonnelAppointment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const data = checks.inputOf(req.body);
    if (data['reviewComment'] !== undefined && data['reviewComment'] !== null && typeof data['reviewComment'] !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '검토 의견 형식이 올바르지 않습니다.');
    }
    const id = req.params['personnelAppointmentId'];
    if (!isIntegerText(id)) {
      throw new ApiError(404, 'PERSONNEL_APPOINTMENT_NOT_FOUND', '인사발령 신청내역을 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT status AS "status" FROM personnel_appointment
        WHERE personnel_appointment_id = CAST(:id AS bigint) FOR UPDATE`,
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PERSONNEL_APPOINTMENT_NOT_FOUND', '인사발령 신청내역을 찾을 수 없습니다.');
      }
      if (rows[0]['status'] !== WAITING) {
        throw new ApiError(409, 'PERSONNEL_APPOINTMENT_ALREADY_PROCESSED', '이미 승인되었거나 반려된 신청건입니다.');
      }
      // 가정: 결재양식은 사용 중인 연계 결재 양식 중 첫 번째를 쓴다.
      const forms = await db.query(
        `SELECT approval_form_id AS "approvalFormId" FROM approval_form
        WHERE use_status = '사용' AND is_linked_approval = true
        ORDER BY approval_form_id LIMIT 1`,
        {},
      );
      const drafters = await db.query(
        `SELECT department_id AS "departmentId" FROM employee
        WHERE employee_id = CAST(:userId AS bigint)`,
        { userId: user.id },
      );
      if (forms.length === 0 || drafters.length === 0 || drafters[0]['departmentId'] === null) {
        throw new ApiError(502, 'APPROVAL_SUBMIT_FAILED', '전자결재 상신에 실패했습니다. 결재양식 또는 기안부서를 확인해 주세요.');
      }
      const docs = await db.query(
        `INSERT INTO approval_document (
          approval_form_id, drafter_id, drafter_department_id, document_number, title,
          approval_status, is_urgent, is_secret, linked_business_type, linked_business_id,
          submitted_at, created_at, updated_at
        ) VALUES (
          CAST(:formId AS bigint), CAST(:userId AS bigint), CAST(:departmentId AS bigint),
          CONCAT('PA-', to_char(now(), 'YYYYMMDDHH24MISSMS'), '-', CAST(:id AS text)),
          '인사발령 승인 요청', :submitted, false, false, 'personnel_appointment', CAST(:id AS bigint),
          now(), now(), now()
        ) RETURNING approval_document_id AS "approvalDocumentId", approval_status AS "approvalStatus"`,
        {
          formId: String(forms[0]['approvalFormId']),
          userId: user.id,
          departmentId: String(drafters[0]['departmentId']),
          id,
          submitted: SUBMITTED_STATUS,
        },
      );
      await db.execute(
        `UPDATE personnel_appointment
        SET status = :status, approval_document_id = CAST(:docId AS bigint), updated_at = now()
        WHERE personnel_appointment_id = CAST(:id AS bigint)`,
        { status: APPROVED, docId: String(docs[0]['approvalDocumentId']), id },
      );
      return {
        status: APPROVED,
        approvalDocumentId: Number(docs[0]['approvalDocumentId']),
        approvalStatus: docs[0]['approvalStatus'],
      };
    });
  }

  @Post('/personnel-appointments/:personnelAppointmentId/reject')
  @HttpCode(200)
  async rejectPersonnelAppointment(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자');
    const data = checks.inputOf(req.body);
    if (data['reviewComment'] !== undefined && data['reviewComment'] !== null && typeof data['reviewComment'] !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '반려 의견 형식이 올바르지 않습니다.');
    }
    const id = req.params['personnelAppointmentId'];
    if (!isIntegerText(id)) {
      throw new ApiError(404, 'PERSONNEL_APPOINTMENT_NOT_FOUND', '인사발령 신청내역을 찾을 수 없습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT status AS "status" FROM personnel_appointment
        WHERE personnel_appointment_id = CAST(:id AS bigint) FOR UPDATE`,
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'PERSONNEL_APPOINTMENT_NOT_FOUND', '인사발령 신청내역을 찾을 수 없습니다.');
      }
      if (rows[0]['status'] !== WAITING) {
        throw new ApiError(409, 'PERSONNEL_APPOINTMENT_ALREADY_PROCESSED', '이미 승인되었거나 반려된 신청건입니다.');
      }
      // 가정: 상태 제약에 반려 값이 없어 상태는 그대로 두고 처리자만 기록한다.
      await db.execute(
        `UPDATE personnel_appointment
        SET processed_by = CAST(:userId AS bigint), updated_at = now()
        WHERE personnel_appointment_id = CAST(:id AS bigint)`,
        { userId: user.id, id },
      );
      return { status: WAITING };
    });
  }
}

