import { useState } from 'react';
import {
  call, useData, Badge, DateText, Filters, Band, DataTable, Pager, Drawer, Pairs, Tiles,
  Form, Field, TextInput, Select, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

const SIZE = 20;

export default function FnSfr01301Page({ role, notify }: PageProps) {
  const [status, setStatus] = useState('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [action, setAction] = useState<{ type: 'approve' | 'reject'; row: Row } | null>(null);
  const [comment, setComment] = useState('');

  const list = useData<Page>(
    () => call<Page>('GET', '/personnel-appointments', role, undefined, { ...applied, page: pageNo, size: SIZE }),
    [role, applied, pageNo],
  );
  const waiting = useData<Page>(
    () => call<Page>('GET', '/personnel-appointments', role, undefined, { status: '대기', page: 0, size: 5 }),
    [role],
  );

  function refresh() {
    list.reload();
    waiting.reload();
  }

  function search() {
    setPageNo(0);
    setApplied({ status, employeeId });
  }

  function reset() {
    setStatus('');
    setEmployeeId('');
    setPageNo(0);
    setApplied({});
  }

  function openAction(type: 'approve' | 'reject', row: Row) {
    setComment('');
    setDetail(null);
    setAction({ type, row });
  }

  async function submitAction() {
    if (!action) return;
    const id = String(action.row['personnelAppointmentId']);
    const body: Row = { reviewComment: comment };
    await call('POST', `/personnel-appointments/${id}/${action.type}`, role, body);
    notify(action.type === 'approve' ? '승인했습니다.' : '반려했습니다.');
    setAction(null);
    refresh();
  }

  function buttons(row: Row) {
    if (row['status'] !== '대기') return null;
    return (
      <span>
        <button type="button" onClick={(e) => { e.stopPropagation(); openAction('approve', row); }}>승인</button>
        <button type="button" onClick={(e) => { e.stopPropagation(); openAction('reject', row); }}>반려</button>
      </span>
    );
  }

  const columns = [
    { key: 'employeeId', label: '대상 임직원', render: (r: Row) => <RefName table="employee" role={role} value={r['employeeId']} /> },
    { key: 'appointmentType', label: '발령 구분' },
    { key: 'appointmentDate', label: '발령일자', render: (r: Row) => <DateText value={r['appointmentDate']} /> },
    { key: 'newPositionName', label: '발령 후 직위' },
    { key: 'status', label: '발령 상태', render: (r: Row) => <Badge value={r['status']} /> },
    { key: 'approvalDocumentId', label: '결재문서', render: (r: Row) => <RefName table="approval_document" role={role} value={r['approvalDocumentId']} /> },
    { key: 'actions', label: '처리', render: buttons },
  ];

  const waitingColumns = [
    { key: 'employeeId', label: '대상 임직원', render: (r: Row) => <RefName table="employee" role={role} value={r['employeeId']} /> },
    { key: 'appointmentDate', label: '발령일자', render: (r: Row) => <DateText value={r['appointmentDate']} /> },
    { key: 'actions', label: '처리', render: buttons },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>신청 현황</h2>
        <Tiles items={[
          ['조회 건수', list.data ? list.data.total : 0],
          ['처리 대기', waiting.data ? waiting.data.total : 0],
        ]} />
      </section>
      <section className="box span-8">
        <h2>인사발령 신청</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="발령 상태">
            <Select value={status} onChange={setStatus} options={[['대기', '대기'], ['승인', '승인'], ['처리완료', '처리완료']]} placeholder="전체" />
          </Field>
          <Field label="대상 임직원 ID">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={list.data ? list.data.total : 0} />
        {list.error ? <ErrorText text={list.error} /> : null}
        <DataTable columns={columns} rows={list.data ? list.data.items : []} onRowClick={setDetail} empty="신청내역이 없습니다." />
        <Pager page={pageNo} size={SIZE} total={list.data ? list.data.total : 0} onPage={setPageNo} />
      </section>
      <section className="box span-4">
        <h2>처리 대기</h2>
        {waiting.error ? <ErrorText text={waiting.error} /> : null}
        <DataTable columns={waitingColumns} rows={waiting.data ? waiting.data.items : []} onRowClick={setDetail} empty="대기 중인 신청이 없습니다." />
      </section>
      {detail ? (
        <Drawer title="인사발령 신청 상세" onClose={() => setDetail(null)}>
          <Pairs items={[
            ['대상 임직원', <RefName table="employee" role={role} value={detail['employeeId']} />],
            ['발령 구분', String(detail['appointmentType'] ?? '')],
            ['발령일자', <DateText value={detail['appointmentDate']} />],
            ['발령 후 직위', String(detail['newPositionName'] ?? '')],
            ['발령 상태', <Badge value={detail['status']} />],
            ['결재문서', <RefName table="approval_document" role={role} value={detail['approvalDocumentId']} />],
          ]} />
          {detail['status'] === '대기' ? (
            <div>
              <button type="button" onClick={() => openAction('approve', detail)}>승인</button>
              <button type="button" onClick={() => openAction('reject', detail)}>반려</button>
            </div>
          ) : null}
        </Drawer>
      ) : null}
      {action ? (
        <Drawer title={action.type === 'approve' ? '인사발령 승인' : '인사발령 반려'} onClose={() => setAction(null)}>
          <Form onSubmit={submitAction} submit={action.type === 'approve' ? '승인' : '반려'} danger={action.type === 'reject'}>
            <Field label="대상 임직원">
              <RefName table="employee" role={role} value={action.row['employeeId']} />
            </Field>
            <Field label={action.type === 'approve' ? '검토 및 승인 의견' : '반려 의견'} wide>
              <TextInput value={comment} onChange={setComment} multiline />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
